export function App() {
  const [prices, setPrices] = useState({});
  useEffect(() => {
    const ws = new WebSocket(URL);
    ws.onmessage = (e) => { const t = JSON.parse(e.data); setPrices(p => ({ ...p, [t.symbol]: t })); };
    return () => ws.close();
